Mutex.ejemplo:
// Go: proteger un mapa compartido con sync.Mutex y defer
type SafeCache struct {
  mu sync.Mutex
  m  map[string]string
}
func (c *SafeCache) Set(k, v string) {
  c.mu.Lock()
  defer c.mu.Unlock()
  c.m[k] = v
}

