Starvation - Livelock.ejemplo:
// Livelock típico con try_lock sin backoff aleatorio ni orden global
while (true) {
  lockA.lock();
  if (lockB.try_lock()) break; // éxito
  lockA.unlock(); // ambos sueltan y reintentan a la vez -> livelock
  // Solución: usar std::scoped_lock(lockA, lockB) o sleep aleatorio
}
